package br.com.sussmartcare.queue.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="queue_entries") public class QueueEntry {@Id private UUID id;@Column(nullable=false,unique=true)private UUID visitId;@Column(nullable=false)private UUID facilityId;@Column(nullable=false,unique=true)private String displayCode;@Column(nullable=false)private String clinicalPriority;@Enumerated(EnumType.STRING)@Column(nullable=false)private QueueEntryStatus status;@Enumerated(EnumType.STRING)@Column(nullable=false)private PresenceState presence;@Column(nullable=false)private Instant enteredAt;private Instant expectedReturnAt;private Instant graceUntil;protected QueueEntry(){}public QueueEntry(UUID visitId,UUID facilityId,String priority){id=UUID.randomUUID();this.visitId=visitId;this.facilityId=facilityId;displayCode="Q-"+id.toString().replace("-","").substring(0,8).toUpperCase();clinicalPriority=priority;status=QueueEntryStatus.WAITING;presence=PresenceState.INSIDE_FACILITY;enteredAt=Instant.now();}
 public void updatePresence(PresenceState state){presence=state;} public void requestReturn(Duration expected,Duration grace){if(presence!=PresenceState.OUTSIDE_FACILITY)return;expectedReturnAt=Instant.now().plus(expected);graceUntil=expectedReturnAt.plus(grace);status=QueueEntryStatus.RETURN_REQUIRED;}
 public void evaluateDeadline(Instant now){if(status==QueueEntryStatus.RETURN_REQUIRED&&expectedReturnAt!=null&&now.isAfter(expectedReturnAt))status=QueueEntryStatus.GRACE_PERIOD;if((status==QueueEntryStatus.RETURN_REQUIRED||status==QueueEntryStatus.GRACE_PERIOD)&&graceUntil!=null&&now.isAfter(graceUntil))status=QueueEntryStatus.MISSED_CALL;}
 public void returned(){boolean late=status==QueueEntryStatus.MISSED_CALL;presence=PresenceState.INSIDE_FACILITY;status=QueueEntryStatus.WAITING;if(late)enteredAt=Instant.now();expectedReturnAt=null;graceUntil=null;} public void call(){if(presence!=PresenceState.INSIDE_FACILITY)throw new IllegalStateException("Paciente não está disponível para chamada");status=QueueEntryStatus.CALLED;}
 public UUID getId(){return id;}public UUID getVisitId(){return visitId;}public UUID getFacilityId(){return facilityId;}public String getDisplayCode(){return displayCode;}public String getClinicalPriority(){return clinicalPriority;}public QueueEntryStatus getStatus(){return status;}public PresenceState getPresence(){return presence;}public Instant getEnteredAt(){return enteredAt;}public Instant getExpectedReturnAt(){return expectedReturnAt;}public Instant getGraceUntil(){return graceUntil;}}
